/* Desktop feature layer. Shared story logic lives in story-core.js. */
KotobaCore.normalize(project);
types.portrait='切换立绘';typeIcons.portrait='people';
const stageRenderer=createStageRenderer(KotobaCore,editorMediaSource);
const baseDialog=dialog;dialog=function(...args){$('#modal').classList.remove('wide');baseDialog(...args)};
let conversionSource='',conversionResult=null,conversionMode='append';
const oldDraw=draw,oldEditor=editor,oldInspector=drawInspector,oldOtherView=otherView,oldValidate=validateProject,oldAddBlock=addBlock,oldResolve=resolvePlayable,oldAdvance=advance;
draw=function(){KotobaCore.normalize(project);oldDraw();if(view==='script')$('.preview-controls .play-group')?.insertAdjacentHTML('beforeend','<button class="btn small" data-action="game-saves">存档 / 读档</button>');if(playing&&!$('.game-save-button'))$('#app').insertAdjacentHTML('beforeend','<button class="game-save-button btn" data-action="game-saves">存档 / 读档</button>')};
editor=function(){return oldEditor().replace('<div class="blocks">','<div class="tool-strip"><span class="micro">剧情编排</span><button class="btn small" data-action="add-portrait">＋ 立绘差分</button><button class="btn small" data-action="scene-effects">场景动画</button><button class="btn small" data-action="text-convert">文本转换</button></div><div class="blocks">')};
drawStage=function(force=false){const el=$('#stage');if(!el)return;const s=project.scenes.find(s=>s.id===(playing?playScene:sceneId))||scene();const index=playing?playIndex:Math.max(0,s.blocks.findIndex(b=>b.id===selected));stageRenderer.render(el,project,s,index,playing&&ended,force,playing?makeStageEffectCompletion(project.id,s.id,index,s.blocks[index]?.id):null)};
const optionList=(map,value)=>Object.entries(map).map(([id,name])=>`<option value="${id}" ${id===value?'selected':''}>${esc(name)}</option>`).join('');
function variantOptions(c,value){return '<option value="">默认立绘</option>'+(c?.variants||[]).map(v=>`<option value="${esc(v.id)}" ${v.id===value?'selected':''}>${esc(v.name)}</option>`).join('')}
function portraitPositionOptions(b) {
  const positions = KotobaCore.positions;
  if (b.type !== 'dialogue') return optionList(positions, b.position || 'center');
  const index = scene().blocks.indexOf(b);
  const actual = KotobaCore.stageAt(project, scene(), index).portrait;
  // Resolve the inherited choice with this block's override removed.
  const prior = b.position ? KotobaCore.stageAt(project, {
    ...scene(), blocks: scene().blocks.slice(0, index).concat({...b, position: undefined})
  }, index).portrait : actual;
  const inherited = positions[prior?.position] || '居中';
  const inheritLabel = '沿用舞台位置 · ' + inherited;
  return optionList({'': inheritLabel, ...positions}, b.position || '');
}
drawInspector=function(){oldInspector();const b=block(),el=$('#inspector');if(!b||!el)return;let html='';if(['dialogue','portrait'].includes(b.type)){const c=character(b.speaker);if(b.type==='portrait')html+=`<div class="field"><label>角色</label><select data-edit="speaker">${charOptions(b.speaker)}</select></div>`;html+=`<div class="field-row"><div class="field"><label>立绘差分</label><select data-edit="variant">${variantOptions(c,b.variant)}</select></div><div class="field"><label>舞台位置</label><select data-edit="position" ${b.type==='dialogue'&&c?.preserveStagePortrait?'disabled':''}>${portraitPositionOptions(b)}</select></div></div>`;if(b.type==='portrait')html+=`<div class="field"><label>显示状态</label><select data-feature="visible"><option value="true" ${b.visible!==false?'selected':''}>显示 / 切换差分</option><option value="false" ${b.visible===false?'selected':''}>隐藏立绘</option></select></div>`;html+=`<p class="field-note">${c?.variants?.length?'差分在角色页管理，默认选项使用角色的默认差分。':'当前角色尚无差分，可前往角色页添加并绑定图片。'}</p>`}if(b.type==='background')html+=effectFields(b,'block')+'<button class="btn small" data-action="preview-effect">重播切换动画</button>';if(html)el.insertAdjacentHTML('afterbegin',html)};
function effectFields(value,scope){return `<div class="field-row"><div class="field"><label>切换动画</label><select data-effect="transition" data-scope="${scope}">${optionList(KotobaCore.effects,value.transition||'none')}</select></div><div class="field"><label>动画时长（毫秒，0–5000）</label><input type="number" min="0" max="5000" step="100" data-effect="duration" data-scope="${scope}" value="${KotobaCore.duration(value.duration)}"></div></div>`}
otherView=function(){if(view==='text')return conversionView();if(view==='projects')return '<div class="full-content" id="projectLibrary"><p class="field-note">正在读取本机工程…</p></div>';if(view!=='people')return oldOtherView();return `<div class="full-content"><div class="card-grid">${project.characters.map(c=>{const img=KotobaCore.portraitAsset(project,c);return `<div class="character-card">${img?`<img class="variant-preview" src="${esc(editorMediaSource(img))}" alt="${esc(c.name)}">`:`<div class="character-face" style="color:${esc(c.color)}">${esc(c.name.slice(-1))}</div>`}<h3>${esc(c.name)}</h3><p>${esc(c.description||'还没有角色介绍')}</p><p class="field-note">${c.variants.length} 个立绘差分 · ${esc(c.variants.find(v=>v.id===c.defaultVariant)?.name||'基础立绘')}</p><div class="card-actions"><button class="btn small" data-action="edit-character" data-id="${esc(c.id)}">编辑角色</button><button class="btn small" data-action="variants" data-id="${esc(c.id)}">管理差分</button></div></div>`}).join('')}<button class="upload-card" data-action="new-character">${ic('people')} 添加新角色</button></div></div>`};
validateProject=function(p){oldValidate(p);KotobaCore.normalize(p);for(const c of p.characters){if(!Array.isArray(c.variants)||c.variants.some(v=>typeof v.id!=='string'||typeof v.name!=='string'||typeof v.asset!=='string'))throw Error('立绘差分格式无效');if(new Set(c.variants.map(v=>v.id)).size!==c.variants.length)throw Error('差分标识重复')}for(const s of p.scenes){if(s.transition&&!KotobaCore.effects[s.transition])throw Error('场景动画格式无效');for(const b of s.blocks){if(b.transition&&!KotobaCore.effects[b.transition])throw Error('切换动画格式无效');if(b.duration!==undefined&&(!Number.isFinite(Number(b.duration))||Number(b.duration)<0||Number(b.duration)>5000))throw Error('动画时长必须在 0–5000 毫秒');if(b.position&&!KotobaCore.positions[b.position])throw Error('立绘位置无效')}}return p};
addBlock=function(type,assetId){if(type!=='portrait'){oldAddBlock(type,assetId);return}change(()=>{const b={id:uid(),type:'portrait',speaker:project.characters[0]?.id||'',variant:'',position:'center',visible:true,text:'切换立绘差分'};const i=scene().blocks.findIndex(b=>b.id===selected);scene().blocks.splice(i<0?scene().blocks.length:i+1,0,b);selected=b.id;view='script';mode='visual'})};
resolvePlayable=function(){let guard=0;while(!ended&&guard++<100){const s=project.scenes.find(s=>s.id===playScene),b=s?.blocks[playIndex];if(b?.type==='portrait'){playIndex++;continue}oldResolve();const now=project.scenes.find(s=>s.id===playScene)?.blocks[playIndex];if(now?.type!=='portrait')return}if(guard>=100)ended=true};
advance=function(){if(stageRenderer.busy())return;oldAdvance()};
function variantManager(id){const c=character(id);if(!c)return;dialog(`${esc(c.name)} · 立绘差分`,`<p>给表情或姿势命名，并为每个差分选择图片。</p><div class="variant-list">${c.variants.map(v=>{const a=asset(v.asset);return `<div class="variant-row">${a?`<img src="${esc(editorMediaSource(a))}" alt="">`:ic('assets')}<div class="details"><strong>${esc(v.name)}${c.defaultVariant===v.id?' · 默认':''}</strong><small>${esc(a?.name||'未绑定图片')}</small></div><button type="button" class="btn small" data-action="default-variant" data-char="${esc(c.id)}" data-id="${esc(v.id)}">设为默认</button><button type="button" class="btn small" data-action="edit-variant" data-char="${esc(c.id)}" data-id="${esc(v.id)}">编辑</button><button type="button" class="btn small" data-action="delete-variant" data-char="${esc(c.id)}" data-id="${esc(v.id)}">移除</button></div>`}).join('')||'<div class="variant-placeholder">还没有立绘差分。先在素材库导入图片，再添加“普通”“微笑”等差分。</div>'}</div><button type="button" class="btn" data-action="new-variant" data-id="${esc(c.id)}">＋ 添加差分</button>`,'完成',()=>{});$('#modal').classList.add('wide')}
function editVariant(charId,id){const c=character(charId),v=c.variants.find(v=>v.id===id)||{id:uid(),name:'微笑',asset:''};$('#modal').close();dialog('编辑立绘差分',`<div class="field"><label>差分名称</label><input name="name" value="${esc(v.name)}" required maxlength="40"></div><div class="field"><label>立绘图片</label><select name="asset" required data-image-selector>${assetOptions(v.asset)}</select></div><p>推荐使用透明背景 PNG。图片从素材库中选择。</p>`,'保存',f=>{change(()=>{const n={...v,name:f.get('name').trim(),asset:f.get('asset')};const i=c.variants.findIndex(x=>x.id===v.id);if(i<0)c.variants.push(n);else c.variants[i]=n;if(!c.defaultVariant)c.defaultVariant=n.id});setTimeout(()=>variantManager(charId),0)})}
function conversionView(){return `<div class="full-content"><div class="conversion-grid"><section class="panel"><div class="panel-head"><span class="panel-title">普通剧本文本</span><button class="btn small" data-action="text-file">导入 TXT</button></div><textarea id="conversionSource" class="conversion-text" placeholder="旁白直接写在一行\n夏川 澪[微笑]：明天也一起回家吧。">${esc(conversionSource)}</textarea><div class="conversion-tools"><button class="btn small" data-action="text-example">填入示例</button><button class="btn small" data-action="scene-to-text">当前场景转为文本</button><button class="btn primary" data-action="parse-text">识别并预览 →</button></div></section><section class="panel"><div class="panel-head"><span class="panel-title">转换预览</span><span class="pill" id="conversionCount">等待识别</span></div><div class="conversion-preview" id="conversionPreview"><p class="field-note">先输入或导入文本，再点击「识别并预览」。转换不会立即改动工程。</p></div><div class="conversion-tools"><select id="conversionMode" aria-label="写入方式"><option value="append">追加到当前场景</option><option value="replace">替换当前场景内容</option></select><button class="btn primary" id="applyConversion" data-action="apply-text" disabled>加入剧本</button><button class="btn small" data-action="export-text">导出文本</button></div></section></div><div class="conversion-help">每行一句：<code>角色[差分]：台词</code>；没有角色前缀的行转为旁白。<br><code>[背景：图片名 | 交叉淡化 | 800]</code>　<code>[立绘：角色名 | 差分名 | 左侧]</code>　<code>[隐藏：角色名]</code><br><code>[CG：图片名 | 交叉淡化 | 700]</code>　<code>[隐藏CG]</code><br><code>[音乐：文件名]</code>　<code>[跳转：场景名]</code>　<code># 新场景名称</code>（包含标题时会新建场景）<br>角色只按工程角色表中的完整名称匹配；未匹配时请手动对应，确认前不会写入。章节支持新建、更新与重命名。TXT 支持 UTF-8 或 GB18030 编码。</div></div>`}
function previewConversion(){conversionSource=$('#conversionSource').value;conversionResult=KotobaCore.parseText(conversionSource,project);$('#conversionCount').textContent=conversionResult.count+' 个剧情块';$('#applyConversion').disabled=!conversionResult.count;$('#conversionMode').disabled=conversionResult.hasHeadings;$('#conversionPreview').innerHTML=(conversionResult.hasHeadings?'<p class="field-note">检测到场景标题，将新建场景。</p>':'')+(conversionResult.warnings.length?`<div class="conversion-warning">${conversionResult.warnings.map(esc).join('<br>')}</div>`:'')+conversionResult.groups.map(g=>`<h3 style="font-size:12px;margin-top:12px">${esc(g.name||scene().name)}</h3>${g.blocks.map(b=>`<div class="conversion-row"><small>${types[b.type]} ${esc(project.characters.concat(conversionResult.newCharacters).find(c=>c.id===b.speaker)?.name||'')}</small>${esc(b.text||b.targetName||'')}</div>`).join('')}`).join('')}
function applyConversion(){previewConversion();const r=conversionResult;if(!r.count)return;const replace=!r.hasHeadings&&$('#conversionMode').value==='replace';const apply=()=>change(()=>{project.characters.push(...r.newCharacters);const added=r.groups.map(g=>({id:uid(),name:g.name||'新场景',blocks:g.blocks}));const targets=new Map([...project.scenes,...added].map(s=>[s.name,s.id]));for(const g of added)for(const b of g.blocks){const links=b.type==='jump'?[b]:b.options||[];for(const link of links){link.target=targets.get(link.targetName)||'';delete link.targetName}}if(r.hasHeadings){project.scenes.push(...added);sceneId=added[0].id;selected=added[0].blocks[0]?.id}else{const blocks=added.flatMap(g=>g.blocks);if(replace)scene().blocks=blocks;else scene().blocks.push(...blocks);selected=blocks[0]?.id}view='script';mode='visual'});if(replace)dialog('替换场景内容',`<p>将替换「${esc(scene().name)}」中的 ${scene().blocks.length} 个剧情块。可通过工程撤销恢复。</p>`,'替换',apply);else apply()}
document.addEventListener('input',e=>{if(e.target.id==='conversionSource'){conversionSource=e.target.value;conversionResult=null;$('#applyConversion').disabled=true;$('#conversionCount').textContent='内容已修改，请重新识别'}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.effect){change(()=>{const target=el.dataset.scope==='scene'?scene():block();if(target)target[el.dataset.effect]=el.dataset.effect==='duration'?KotobaCore.duration(el.value):el.value});return}if(el.dataset.feature==='visible')change(()=>block().visible=el.value==='true')});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;const handled=['add-portrait','scene-effects','preview-effect','variants','new-variant','edit-variant','delete-variant','default-variant','text-convert','text-file','text-example','scene-to-text','parse-text','apply-text','export-text','game-saves','save-slot','load-slot','projects','library-new','library-open','library-delete','library-restore'];if(!handled.includes(a))return;e.preventDefault();e.stopImmediatePropagation();switch(a){case'add-portrait':addBlock('portrait');break;case'scene-effects':dialog('场景切换动画',`<p>进入此场景时使用的动画。背景块还可单独设置切换动画。</p>${effectFields(scene(),'scene')}`,'完成',()=>{});break;case'preview-effect':drawStage(true);break;case'variants':variantManager(id);break;case'new-variant':editVariant(id);break;case'edit-variant':editVariant(b.dataset.char,id);break;case'default-variant':change(()=>character(b.dataset.char).defaultVariant=id);$('#modal').close();variantManager(b.dataset.char);break;case'delete-variant':change(()=>{const c=character(b.dataset.char);c.variants=c.variants.filter(v=>v.id!==id);if(c.defaultVariant===id)c.defaultVariant='';project.scenes.forEach(s=>s.blocks.forEach(x=>{if(x.speaker===c.id&&x.variant===id)x.variant=''}))});$('#modal').close();variantManager(b.dataset.char);break;case'text-convert':view='text';draw();break;case'parse-text':previewConversion();break;case'apply-text':applyConversion();break;case'text-example':conversionSource='[背景：午后的教室 | 交叉淡化 | 900]\n七月的风穿过窗边。\n夏川 澪：明天也一起回家吧。\n望月 晴：嗯，说好了。';draw();break;case'scene-to-text':conversionSource=KotobaCore.serializeText(project,scene());draw();break;case'text-file':dialog('导入文本',`<div class="field"><label>文本文件编码</label><select name="encoding"><option value="utf-8">UTF-8（推荐）</option><option value="gb18030">GB18030 / GBK</option></select></div>`,'选择文件',f=>{const encoding=f.get('encoding');pickFile('.txt,.text',async file=>{if(file.size>2*1024*1024){notify('文本超过 2 MB，请分段导入');return}conversionSource=new TextDecoder(encoding).decode(await file.arrayBuffer());draw()})});break;case'export-text':exportStoryText();break;case'game-saves':showGameSaves();break;case'save-slot':writeGameSlot(Number(id));break;case'load-slot':readGameSlot(Number(id));break;case'projects':view='projects';draw();loadProjectLibrary();break;case'library-new':createLibraryProject();break;case'library-open':openLibraryProject(id);break;case'library-delete':deleteLibraryProject(id);break;case'library-restore':restoreLibraryProject(id);break}},true);
async function exportStoryText(){try{const text=$('#conversionSource')?.value||KotobaCore.serializeText(project,scene());const r=await window.desktop.save({name:project.title+'-剧本.txt',text,kind:'text'});if(!r.canceled)notify('剧本文本已保存')}catch(e){notify('导出失败：'+e.message)}}
async function buildOfflineGame(input){const p=input||await portableProject(),data=JSON.stringify(p).replace(/</g,'\\u003c');const css=await window.desktop.featureFile('style.css')+'\n'+await window.desktop.featureFile('features.css');return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.title)}</title><style>${css}body{background:#24372e}.stage{position:fixed;inset:0;aspect-ratio:auto}.dialogue{left:10%;right:10%;bottom:7%;padding:32px;min-height:130px}.dialogue p{font-size:20px}.speaker{font-size:16px!important}.scene-label{top:30px;left:30px}.choices{left:30%;right:30%}.game-toolbar{position:fixed;right:20px;top:20px;display:flex;gap:8px;z-index:20}.game-toolbar button{background:#fffef0e8}.stage-character{height:96%}#gameSavePanel{position:fixed;inset:15% 20%;z-index:50;background:#fffdf2;padding:25px;border-radius:12px;overflow:auto;box-shadow:0 10px 100px #0008}#gameSavePanel[hidden]{display:none}</style><div id="stage" class="stage"></div><div class="game-toolbar"><button class="btn" id="saves">存档 / 读档</button><button class="btn" id="restart" hidden>重新开始</button></div><div id="gameSavePanel" hidden></div><script>const KotobaCore=(${createStoryCore.toString()})();${createStageRenderer.toString()}\n${startOfflineGame.toString()}\nstartOfflineGame(${data});</script></html>`}
exportGame=async function(){try{const html=await buildOfflineGame();const done=await download(project.title+'-试玩.html',html,'text/html');if(done?.path)showHtmlExportResult(done.path);else if(done!==false)notify('试玩已导出，包含差分、场景动画与存读档')}catch(e){notify('导出失败：'+e.message)}};
openNativeProject=async function(){try{const r=await window.desktop.open();if(!r)return;const p=validateProject(JSON.parse(r.text));dialog('打开工程',`<p>载入「${esc(p.title)}」？已保存的当前工程会保留。</p>`,'打开',async()=>{await window.desktop.accept(r.path);activateProject(p)})}catch(e){notify('打开失败：'+e.message)}};
draw();
